#' Method to approximate Pr(active AE rate > placebo AE rate) in a blinded
#' setting.
#'
#' @description Note that this function is quite rudimentary and only suitable
#'   for quick-and-dirty approximations. Use \code{\link{stan_bssd}} for a more
#'   rigorous analysis, preferably with an informative MAP prior generated by
#'   \code{\link{stan_map_patient_data}} or \code{\link{stan_map_summary_data}}.
#'
#' @param y integer, number of subjects with adverse events across both arms.
#' @param time numeric, total time at risk (units = study duration).
#' @param prob_arm1 numeric, probability of being randomized to placebo (arm1).
#' @param pi1_alpha numeric, first shape param of beta prior distribution on
#'   unit-time event probability in placebo (arm1).
#' @param pi1_beta numeric, second shape param of beta prior distribution on
#'   unit-time event probability in placebo (arm1).
#' @param pi2_alpha numeric, first shape param of beta prior distribution on
#'   unit-time event probability in active (arm2).
#' @param pi2_beta numeric, second shape param of beta prior distribution on
#'   unit-time event probability in active (arm2).
#' @param num_samples integer.
#' @param seed integer, used to initialize the random number generator for
#' 'rbeta' function to add function result reproducibility.
#'
#' @return numeric, Pr(active AE rate > placebo AE rate).
#'
#' @importFrom stats rbeta dbinom
#'
#' @export
#'
#' @examples
#' approx_bssd(y = 10, time = 100, prob_arm1 = 0.5,
#' pi1_alpha = 9, pi1_beta = 92, pi2_alpha = 0.3, pi2_beta = 0.3,seed = NULL)
approx_bssd <- function(y, time, prob_arm1,
                        pi1_alpha, pi1_beta,
                        pi2_alpha = 0.3, pi2_beta = 0.3,
                        num_samples = 50000, seed = NULL) {

  # set the seed value if provided as parameter in the call.
  if (!is.null(seed)) {
    # check if the seed as passed is valid
    if (!is.numeric(seed) || length(seed) != 1 || seed != floor(seed) ||
        seed < 0) {
      stop("Seed must be a non-negative integer.")
    }
    set.seed(seed)
  }

  # Perform Interface value checks:
  if (!is.numeric(y) || length(y) != 1 || y != floor(y) || y < 0 ||
      is.na(y)) {
    stop("Y must be non-missing and a non-negative integer.")
  }
  if (!is.numeric(time) || length(time) != 1 || time < 0 || is.na(time)) {
    stop("Time must be non-missing and a non-negative rational number.")
  }
  if (!is.numeric(prob_arm1) || length(prob_arm1) != 1 || prob_arm1 < 0 ||
      prob_arm1 > 1 || is.na(prob_arm1)) {
    stop("Prob_arm1 must be between zero and one.")
  }
  if (!is.numeric(pi1_alpha) || length(pi1_alpha) != 1 || pi1_alpha < 0 ||
     is.na(pi1_alpha)) {
    stop("Pi1_alpha must be non-missing and a non-negative rational number.")
  }
  if (!is.numeric(pi1_beta) || length(pi1_beta) != 1 || pi1_beta < 0 ||
     is.na(pi1_beta)) {
    stop("Pi1_beta must be non-missing and a non-negative rational number.")
  }
  if (!is.numeric(pi2_alpha) || length(pi2_alpha) != 1 || pi2_alpha < 0 ||
     is.na(pi2_alpha)) {
    stop("Pi2_alpha must be non-missing and a non-negative rational number.")
  }
  if (!is.numeric(pi2_beta) || length(pi2_beta) != 1 || pi2_beta < 0 ||
     is.na(pi2_beta)) {
    stop("Pi2_beta must be non-missing and a non-negative rational number.")
  }
  if (!is.numeric(num_samples) || length(num_samples) != 1 ||
      num_samples != floor(num_samples) || num_samples < 0) {
    stop("Num_samples must be a non-negative integer.")
  }
  if (pi1_alpha <= 0 | pi1_beta <= 0 | pi2_alpha <= 0 | pi2_beta <= 0) {
    stop(paste0("Pi1_alpha, pi1_beta, pi2_alpha, and pi2_beta ",
                "should be strictly positive."))
  }

  Nc <- round(time * prob_arm1)
  Na <- round(time * (1 - prob_arm1))

  if (y > min(Nc, Na)) {
    stop(paste0("The number of observed events y, cannot be larger than ",
                "the smallest treatment group."))
  }

  C <- rbeta(n = num_samples, pi1_alpha, pi1_beta)
  A <- rbeta(n = num_samples, pi2_alpha, pi2_beta)
  pR <- rep(0, num_samples)
  Rc <- 0
  while (Rc <= y) {
    Ra <- y - Rc
    pR <- pR + dbinom(Rc, Nc, C) * dbinom(Ra, Na, A)
    Rc <- Rc + 1
  }
  sum(pR[A > C]) / sum(pR)

  # The above is identical to the following line arrived at via Bayes Theorem
  # mean(pR[A>C])*sum(A>C) / (mean(pR[A>C])*sum(A>C) + mean(pR[A<C])*sum(A<C))
  # (noting that num_samples divisor cancels out from numerator and
  # denominator)
}
